function cone(g){ctx.save();ctx.beginPath();ctx.moveTo(g.x,g.y);for(let i=0;i<=44;i++){const a=g.angle-.49+i/44*.98;let r=0;for(r=10;r<220;r+=7){const x=g.x+Math.cos(a)*r,y=g.y+Math.sin(a)*r;if(x<65||x>1015||y<105||y>600||game.stage.walls.some(w=>x>w[0]&&x<w[0]+w[2]&&y>w[1]&&y<w[1]+w[3]))break;}ctx.lineTo(g.x+Math.cos(a)*r,g.y+Math.sin(a)*r);}ctx.closePath();const grad=ctx.createRadialGradient(g.x,g.y,10,g.x,g.y,220);grad.addColorStop(0,game.alert>.3?'#f5a78b66':'#f7dda051');grad.addColorStop(1,'#f5d99c08');ctx.fillStyle=grad;ctx.fill();ctx.restore();}
