 // Marble dividers also block the guards' view.
 for(const [x,y,w,h] of game.stage.walls){rr(x+4,y+11,w,h,5,'#272c4244');rr(x,y,w,h,5,'#4a4b65','#898496');rr(x-3,y-8,w+6,13,3,'#b2a6ae');rr(x+6,y+4,w-12,h-10,3,'#6a657c');line([[x+10,y+7],[x+w-10,y+7]],'#928698',2);if(w>60){rr(x+w/2-15,y+13,30,13,2,'#d4bc91');text('𓆟',x+w/2,y+23,10,'#685a63');}}
 for(const f of game.fish){ellipse(f.x,f.y+25,36,12,'#30314644');rr(f.x-26,f.y+1,52,29,4,f.taken?'#77778b':'#9b93a3');rr(f.x-32,f.y-3,64,10,4,f.taken?'#8a8497':'#c9b9bc');rr(f.x-14,f.y+15,28,7,2,f.taken?'#9791a0':'#d7bd8f');if(!f.taken){const float=Math.sin(clock*2.4+f.id*1.7)*4;const glow=ctx.createRadialGradient(f.x,f.y-17,0,f.x,f.y-17,47);glow.addColorStop(0,'#f3d28c40');glow.addColorStop(1,'#f3d28c00');ctx.fillStyle=glow;ctx.fillRect(f.x-50,f.y-65,100,100);fish(f.x+4,f.y-20+float,.7,game.level===2&&f.id===6?'#ffdc77':colors.gold);star(f.x-31,f.y-27+float,4+Math.sin(clock*3+f.id)*2);star(f.x+28,f.y-39-float,3,'#f8e9b8');}else{text('✓',f.x,f.y-12,17,'#b0d4be');}}
