 const actors=game.guards.map(g=>({y:g.y,draw:()=>guard(g)}));actors.push({y:game.player.y,draw:()=>spriteCat(game.player)});actors.sort((a,b)=>a.y-b.y).forEach(a=>a.draw());
 if(game.mode==='playing'&&!game.player.hidden&&game.nearbyBox){rr(game.player.x-52,game.player.y-79,104,25,6,'#1a243ce8');text('SPACE かくれる',game.player.x,game.player.y-62,10,'#daead6');}
